import { z } from "zod";

// Schema for the Lambda event input
export const CsvChunkerEventSchema = z.object({
  sourceS3Path: z.string().min(1, "Source S3 path is required"),
  chunkSizeRows: z.number().int().positive().default(1000),
});

export type CsvChunkerEvent = z.infer<typeof CsvChunkerEventSchema>;

// Schema for the Lambda response
export const CsvChunkerResponseSchema = z.object({
  chunkPaths: z.array(z.string()),
  totalChunks: z.number().int().nonnegative(),
  totalRows: z.number().int().nonnegative(),
});

export type CsvChunkerResponse = z.infer<typeof CsvChunkerResponseSchema>;

// Internal types for S3 operations
export type S3Location = {
  bucket: string;
  key: string;
};

export type CsvChunk = {
  headers: string[];
  rows: string[][];
  chunkIndex: number;
};

