import { parseS3Path } from "./csv-chunker";

describe("CSV Chunker", () => {
  describe("parseS3Path", () => {
    it("should parse s3:// path into bucket and key", () => {
      const result = parseS3Path("s3://my-bucket/path/to/file.csv");

      expect(result).toEqual({
        bucket: "my-bucket",
        key: "path/to/file.csv",
      });
    });

    it("should parse s3:// path with nested folders", () => {
      const result = parseS3Path(
        "s3://my-bucket/deep/nested/folder/structure/file.csv"
      );

      expect(result).toEqual({
        bucket: "my-bucket",
        key: "deep/nested/folder/structure/file.csv",
      });
    });

    it("should throw error for invalid s3 path format", () => {
      expect(() => parseS3Path("invalid-path")).toThrow(
        "Invalid S3 path format"
      );
    });

    it("should throw error for non-s3:// protocol", () => {
      expect(() => parseS3Path("http://bucket/key")).toThrow(
        "Invalid S3 path format"
      );
    });
  });
});

