import { parseS3Path, generateChunkPath } from "./csv-chunker";

describe("CSV Chunker", () => {
  describe("parseS3Path", () => {
    it("should parse s3:// path into bucket and key", () => {
      const result = parseS3Path("s3://my-bucket/path/to/file.csv");

      expect(result).toEqual({
        bucket: "my-bucket",
        key: "path/to/file.csv",
      });
    });

    it("should parse s3:// path with nested folders", () => {
      const result = parseS3Path(
        "s3://my-bucket/deep/nested/folder/structure/file.csv"
      );

      expect(result).toEqual({
        bucket: "my-bucket",
        key: "deep/nested/folder/structure/file.csv",
      });
    });

    it("should throw error for invalid s3 path format", () => {
      expect(() => parseS3Path("invalid-path")).toThrow(
        "Invalid S3 path format"
      );
    });

    it("should throw error for non-s3:// protocol", () => {
      expect(() => parseS3Path("http://bucket/key")).toThrow(
        "Invalid S3 path format"
      );
    });
  });

  describe("generateChunkPath", () => {
    it("should generate chunk path with zero-padded index", () => {
      const sourceLocation = { bucket: "my-bucket", key: "data/file.csv" };
      const result = generateChunkPath(sourceLocation, 0);

      expect(result).toBe("s3://my-bucket/data/file-chunk-001.csv");
    });

    it("should generate chunk path for multi-digit chunk index", () => {
      const sourceLocation = { bucket: "my-bucket", key: "data/file.csv" };
      const result = generateChunkPath(sourceLocation, 42);

      expect(result).toBe("s3://my-bucket/data/file-chunk-043.csv");
    });

    it("should handle files without extension", () => {
      const sourceLocation = { bucket: "my-bucket", key: "data/file" };
      const result = generateChunkPath(sourceLocation, 0);

      expect(result).toBe("s3://my-bucket/data/file-chunk-001");
    });

    it("should handle nested folder structures", () => {
      const sourceLocation = {
        bucket: "my-bucket",
        key: "deep/nested/path/file.csv",
      };
      const result = generateChunkPath(sourceLocation, 99);

      expect(result).toBe(
        "s3://my-bucket/deep/nested/path/file-chunk-100.csv"
      );
    });
  });
});

