import { S3Location } from "./csv-chunker.types";

export const parseS3Path = (s3Path: string): S3Location => {
  const s3UrlPattern = /^s3:\/\/([^/]+)\/(.+)$/;
  const match = s3Path.match(s3UrlPattern);

  if (!match) {
    throw new Error("Invalid S3 path format");
  }

  return {
    bucket: match[1],
    key: match[2],
  };
};

export const generateChunkPath = (
  sourceLocation: S3Location,
  chunkIndex: number
): string => {
  const { bucket, key } = sourceLocation;
  const lastSlashIndex = key.lastIndexOf("/");
  const lastDotIndex = key.lastIndexOf(".");

  const hasExtension = lastDotIndex > lastSlashIndex;
  const chunkNumber = String(chunkIndex + 1).padStart(3, "0");

  if (hasExtension) {
    const baseName = key.substring(0, lastDotIndex);
    const extension = key.substring(lastDotIndex);
    return `s3://${bucket}/${baseName}-chunk-${chunkNumber}${extension}`;
  }

  return `s3://${bucket}/${key}-chunk-${chunkNumber}`;
};

