import { S3Location, CsvChunk } from "./csv-chunker.types";
import { S3Operations } from "./s3-operations";
import { parseString } from "@fast-csv/parse";
import { format } from "@fast-csv/format";

export const parseS3Path = (s3Path: string): S3Location => {
  const s3UrlPattern = /^s3:\/\/([^/]+)\/(.+)$/;
  const match = s3Path.match(s3UrlPattern);

  if (!match) {
    throw new Error("Invalid S3 path format");
  }

  return {
    bucket: match[1],
    key: match[2],
  };
};

export const generateChunkPath = (
  sourceLocation: S3Location,
  chunkIndex: number
): string => {
  const { bucket, key } = sourceLocation;
  const lastSlashIndex = key.lastIndexOf("/");
  const lastDotIndex = key.lastIndexOf(".");

  const hasExtension = lastDotIndex > lastSlashIndex;
  const chunkNumber = String(chunkIndex + 1).padStart(3, "0");

  if (hasExtension) {
    const baseName = key.substring(0, lastDotIndex);
    const extension = key.substring(lastDotIndex);
    return `s3://${bucket}/${baseName}-chunk-${chunkNumber}${extension}`;
  }

  return `s3://${bucket}/${key}-chunk-${chunkNumber}`;
};

export const chunkCsvData = (
  headers: string[],
  rows: string[][],
  chunkSizeRows: number
): CsvChunk[] => {
  if (rows.length === 0) {
    return [];
  }

  const chunks: CsvChunk[] = [];

  for (let i = 0; i < rows.length; i += chunkSizeRows) {
    const chunkRows = rows.slice(i, i + chunkSizeRows);
    chunks.push({
      headers,
      rows: chunkRows,
      chunkIndex: chunks.length,
    });
  }

  return chunks;
};

export const readCsvFromS3 = async (
  location: S3Location,
  s3Operations: S3Operations
): Promise<{ headers: string[]; rows: string[][] }> => {
  const csvContent = await s3Operations.getObject(location.bucket, location.key);

  if (!csvContent || csvContent.trim() === "") {
    return { headers: [], rows: [] };
  }

  return new Promise((resolve, reject) => {
    const records: string[][] = [];

    parseString(csvContent, { headers: false })
      .on("data", (row: string[]) => {
        records.push(row);
      })
      .on("error", reject)
      .on("end", () => {
        if (records.length === 0) {
          resolve({ headers: [], rows: [] });
          return;
        }

        const [headers, ...rows] = records;
        resolve({ headers, rows });
      });
  });
};

export const writeCsvChunkToS3 = async (
  chunk: CsvChunk,
  location: S3Location,
  s3Operations: S3Operations
): Promise<void> => {
  const allRows = [chunk.headers, ...chunk.rows];
  const csvContent = stringify(allRows);

  await s3Operations.putObject(location.bucket, location.key, csvContent);
};

