import {
  parseS3Path,
  generateChunkPath,
  chunkCsvData,
  readCsvFromS3,
  writeCsvChunkToS3,
} from "./csv-chunker";
import { CsvChunk, S3Location } from "./csv-chunker.types";
import { S3Operations } from "./s3-operations";

describe("CSV Chunker", () => {
  describe("parseS3Path", () => {
    it("should parse s3:// path into bucket and key", () => {
      const result = parseS3Path("s3://my-bucket/path/to/file.csv");

      expect(result).toEqual({
        bucket: "my-bucket",
        key: "path/to/file.csv",
      });
    });

    it("should parse s3:// path with nested folders", () => {
      const result = parseS3Path(
        "s3://my-bucket/deep/nested/folder/structure/file.csv"
      );

      expect(result).toEqual({
        bucket: "my-bucket",
        key: "deep/nested/folder/structure/file.csv",
      });
    });

    it("should throw error for invalid s3 path format", () => {
      expect(() => parseS3Path("invalid-path")).toThrow(
        "Invalid S3 path format"
      );
    });

    it("should throw error for non-s3:// protocol", () => {
      expect(() => parseS3Path("http://bucket/key")).toThrow(
        "Invalid S3 path format"
      );
    });
  });

  describe("generateChunkPath", () => {
    it("should generate chunk path with zero-padded index", () => {
      const sourceLocation = { bucket: "my-bucket", key: "data/file.csv" };
      const result = generateChunkPath(sourceLocation, 0);

      expect(result).toBe("s3://my-bucket/data/file-chunk-001.csv");
    });

    it("should generate chunk path for multi-digit chunk index", () => {
      const sourceLocation = { bucket: "my-bucket", key: "data/file.csv" };
      const result = generateChunkPath(sourceLocation, 42);

      expect(result).toBe("s3://my-bucket/data/file-chunk-043.csv");
    });

    it("should handle files without extension", () => {
      const sourceLocation = { bucket: "my-bucket", key: "data/file" };
      const result = generateChunkPath(sourceLocation, 0);

      expect(result).toBe("s3://my-bucket/data/file-chunk-001");
    });

    it("should handle nested folder structures", () => {
      const sourceLocation = {
        bucket: "my-bucket",
        key: "deep/nested/path/file.csv",
      };
      const result = generateChunkPath(sourceLocation, 99);

      expect(result).toBe(
        "s3://my-bucket/deep/nested/path/file-chunk-100.csv"
      );
    });
  });

  describe("chunkCsvData", () => {
    it("should split CSV data into chunks with headers", () => {
      const headers = ["id", "name", "email"];
      const rows = [
        ["1", "Alice", "alice@example.com"],
        ["2", "Bob", "bob@example.com"],
        ["3", "Charlie", "charlie@example.com"],
      ];

      const chunks = chunkCsvData(headers, rows, 2);

      expect(chunks).toHaveLength(2);
      expect(chunks[0]).toEqual({
        headers: ["id", "name", "email"],
        rows: [
          ["1", "Alice", "alice@example.com"],
          ["2", "Bob", "bob@example.com"],
        ],
        chunkIndex: 0,
      });
      expect(chunks[1]).toEqual({
        headers: ["id", "name", "email"],
        rows: [["3", "Charlie", "charlie@example.com"]],
        chunkIndex: 1,
      });
    });

    it("should handle exact division into chunks", () => {
      const headers = ["col1", "col2"];
      const rows = [
        ["a", "b"],
        ["c", "d"],
        ["e", "f"],
        ["g", "h"],
      ];

      const chunks = chunkCsvData(headers, rows, 2);

      expect(chunks).toHaveLength(2);
      expect(chunks[0].rows).toHaveLength(2);
      expect(chunks[1].rows).toHaveLength(2);
    });

    it("should return single chunk when rows less than chunk size", () => {
      const headers = ["id", "value"];
      const rows = [
        ["1", "test1"],
        ["2", "test2"],
      ];

      const chunks = chunkCsvData(headers, rows, 10);

      expect(chunks).toHaveLength(1);
      expect(chunks[0].rows).toHaveLength(2);
      expect(chunks[0].chunkIndex).toBe(0);
    });

    it("should handle empty rows", () => {
      const headers = ["id", "value"];
      const rows: string[][] = [];

      const chunks = chunkCsvData(headers, rows, 10);

      expect(chunks).toHaveLength(0);
    });

    it("should preserve headers in all chunks", () => {
      const headers = ["col1", "col2", "col3"];
      const rows = [
        ["a", "b", "c"],
        ["d", "e", "f"],
        ["g", "h", "i"],
      ];

      const chunks = chunkCsvData(headers, rows, 1);

      expect(chunks).toHaveLength(3);
      chunks.forEach((chunk) => {
        expect(chunk.headers).toEqual(["col1", "col2", "col3"]);
      });
    });
  });

  describe("readCsvFromS3", () => {
    it("should read and parse CSV from S3", async () => {
      const csvContent = `id,name,email
1,Alice,alice@example.com
2,Bob,bob@example.com`;

      const mockS3: S3Operations = {
        getObject: jest.fn().mockResolvedValue(csvContent),
        putObject: jest.fn(),
      };

      const result = await readCsvFromS3(
        { bucket: "my-bucket", key: "data/file.csv" },
        mockS3
      );

      expect(result.headers).toEqual(["id", "name", "email"]);
      expect(result.rows).toEqual([
        ["1", "Alice", "alice@example.com"],
        ["2", "Bob", "bob@example.com"],
      ]);
      expect(mockS3.getObject).toHaveBeenCalledWith(
        "my-bucket",
        "data/file.csv"
      );
    });

    it("should handle CSV with only headers", async () => {
      const csvContent = `id,name,email`;

      const mockS3: S3Operations = {
        getObject: jest.fn().mockResolvedValue(csvContent),
        putObject: jest.fn(),
      };

      const result = await readCsvFromS3(
        { bucket: "test-bucket", key: "test.csv" },
        mockS3
      );

      expect(result.headers).toEqual(["id", "name", "email"]);
      expect(result.rows).toEqual([]);
    });

    it("should handle empty CSV file", async () => {
      const mockS3: S3Operations = {
        getObject: jest.fn().mockResolvedValue(""),
        putObject: jest.fn(),
      };

      const result = await readCsvFromS3(
        { bucket: "test-bucket", key: "empty.csv" },
        mockS3
      );

      expect(result.headers).toEqual([]);
      expect(result.rows).toEqual([]);
    });
  });

  describe("writeCsvChunkToS3", () => {
    it("should write CSV chunk to S3", async () => {
      const mockS3: S3Operations = {
        getObject: jest.fn(),
        putObject: jest.fn().mockResolvedValue(undefined),
      };

      const chunk: CsvChunk = {
        headers: ["id", "name"],
        rows: [
          ["1", "Alice"],
          ["2", "Bob"],
        ],
        chunkIndex: 0,
      };

      await writeCsvChunkToS3(
        chunk,
        { bucket: "my-bucket", key: "output/chunk-001.csv" },
        mockS3
      );

      expect(mockS3.putObject).toHaveBeenCalledWith(
        "my-bucket",
        "output/chunk-001.csv",
        expect.stringContaining("id,name")
      );
      expect(mockS3.putObject).toHaveBeenCalledWith(
        "my-bucket",
        "output/chunk-001.csv",
        expect.stringContaining("1,Alice")
      );
      expect(mockS3.putObject).toHaveBeenCalledWith(
        "my-bucket",
        "output/chunk-001.csv",
        expect.stringContaining("2,Bob")
      );
    });

    it("should write chunk with headers only", async () => {
      const mockS3: S3Operations = {
        getObject: jest.fn(),
        putObject: jest.fn().mockResolvedValue(undefined),
      };

      const chunk: CsvChunk = {
        headers: ["col1", "col2", "col3"],
        rows: [],
        chunkIndex: 0,
      };

      await writeCsvChunkToS3(
        chunk,
        { bucket: "bucket", key: "key" },
        mockS3
      );

      expect(mockS3.putObject).toHaveBeenCalledWith(
        "bucket",
        "key",
        "col1,col2,col3\n"
      );
    });
  });
});

