import { CsvChunkerEvent, CsvChunkerResponse } from "./csv-chunker.types";
import { S3Operations } from "./s3-operations";

describe("CSV Chunker Lambda Handler", () => {
  it("should process CSV file and return chunk paths", async () => {
    const csvContent = `id,name,email
1,Alice,alice@example.com
2,Bob,bob@example.com
3,Charlie,charlie@example.com`;

    const writtenChunks: Record<string, string> = {};

    const mockS3: S3Operations = {
      getObject: jest.fn().mockResolvedValue(csvContent),
      putObject: jest.fn().mockImplementation(async (bucket, key, body) => {
        writtenChunks[`s3://${bucket}/${key}`] = body;
      }),
    };

    const event: CsvChunkerEvent = {
      sourceS3Path: "s3://my-bucket/data/input.csv",
      chunkSizeRows: 2,
    };

    const result = (await handler(event, mockS3)) as CsvChunkerResponse;

    expect(result.totalChunks).toBe(2);
    expect(result.totalRows).toBe(3);
    expect(result.chunkPaths).toEqual([
      "s3://my-bucket/data/input-chunk-001.csv",
      "s3://my-bucket/data/input-chunk-002.csv",
    ]);

    expect(writtenChunks["s3://my-bucket/data/input-chunk-001.csv"]).toContain(
      "id,name,email"
    );
    expect(writtenChunks["s3://my-bucket/data/input-chunk-001.csv"]).toContain(
      "1,Alice,alice@example.com"
    );
    expect(writtenChunks["s3://my-bucket/data/input-chunk-002.csv"]).toContain(
      "3,Charlie,charlie@example.com"
    );
  });

  it("should handle single chunk when rows less than chunk size", async () => {
    const csvContent = `col1,col2
a,b
c,d`;

    const mockS3: S3Operations = {
      getObject: jest.fn().mockResolvedValue(csvContent),
      putObject: jest.fn().mockResolvedValue(undefined),
    };

    const event: CsvChunkerEvent = {
      sourceS3Path: "s3://bucket/file.csv",
      chunkSizeRows: 10,
    };

    const result = (await handler(event, mockS3)) as CsvChunkerResponse;

    expect(result.totalChunks).toBe(1);
    expect(result.totalRows).toBe(2);
    expect(result.chunkPaths).toEqual(["s3://bucket/file-chunk-001.csv"]);
  });

  it("should handle empty CSV file", async () => {
    const mockS3: S3Operations = {
      getObject: jest.fn().mockResolvedValue(""),
      putObject: jest.fn().mockResolvedValue(undefined),
    };

    const event: CsvChunkerEvent = {
      sourceS3Path: "s3://bucket/empty.csv",
      chunkSizeRows: 100,
    };

    const result = (await handler(event, mockS3)) as CsvChunkerResponse;

    expect(result.totalChunks).toBe(0);
    expect(result.totalRows).toBe(0);
    expect(result.chunkPaths).toEqual([]);
    expect(mockS3.putObject).not.toHaveBeenCalled();
  });

  it("should use default chunk size when not specified", async () => {
    const csvContent = `id,value
${Array.from({ length: 1500 }, (_, i) => `${i + 1},val${i + 1}`).join("\n")}`;

    const mockS3: S3Operations = {
      getObject: jest.fn().mockResolvedValue(csvContent),
      putObject: jest.fn().mockResolvedValue(undefined),
    };

    const event: CsvChunkerEvent = {
      sourceS3Path: "s3://bucket/large.csv",
      chunkSizeRows: 1000,
    };

    const result = (await handler(event, mockS3)) as CsvChunkerResponse;

    expect(result.totalChunks).toBe(2);
    expect(result.totalRows).toBe(1500);
    expect(result.chunkPaths).toHaveLength(2);
  });

  it("should validate event schema", async () => {
    const mockS3: S3Operations = {
      getObject: jest.fn(),
      putObject: jest.fn(),
    };

    const invalidEvent = {
      sourceS3Path: "",
      chunkSizeRows: -5,
    };

    await expect(handler(invalidEvent as CsvChunkerEvent, mockS3)).rejects.toThrow();
  });
});

