import {
  CsvChunkerEvent,
  CsvChunkerEventSchema,
  CsvChunkerResponse,
  CsvChunkerResponseSchema,
} from "./csv-chunker.types";
import { S3Operations, createS3Operations } from "./s3-operations";
import {
  parseS3Path,
  readCsvFromS3,
  chunkCsvData,
  writeCsvChunkToS3,
  generateChunkPath,
} from "./csv-chunker";
import { S3Client } from "@aws-sdk/client-s3";

export const handler = async (
  event: CsvChunkerEvent,
  s3Operations?: S3Operations
): Promise<CsvChunkerResponse> => {
  const validatedEvent = CsvChunkerEventSchema.parse(event);

  const s3 = s3Operations ?? createS3Operations(new S3Client({}));

  const sourceLocation = parseS3Path(validatedEvent.sourceS3Path);

  const { headers, rows } = await readCsvFromS3(sourceLocation, s3);

  if (rows.length === 0) {
    return CsvChunkerResponseSchema.parse({
      chunkPaths: [],
      totalChunks: 0,
      totalRows: 0,
    });
  }

