import * as cdk from 'aws-cdk-lib'
import { Construct } from 'constructs'
import { LambdaFunction } from '../../../../common/constructs/lambda-function/lambdaFunction'

export interface AttributeGeneratorIrelandProps {
	env: string
	serviceName: string
	productEnrichmentBucket: cdk.aws_s3.IBucket
}

export class AttributesGeneratorIreland extends cdk.Stack {
	constructor(scope: Construct, id: string, props: AttributeGeneratorIrelandProps) {
		super(scope, id)

		const { env, serviceName, productEnrichmentBucket } = props

		const BATCH_SIZE_BOOHOO = props.env === 'prod' ? 2500 : 40 // ⚠️ adjust
		const BATCH_SIZE_MIRAKL = props.env === 'prod' ? 3000 : 40 // ⚠️ adjust
		const BATCH_RATE_MINUTES = props.env === 'prod' ? 60 : 720 // ⚠️ adjust

		const setupLambda = new LambdaFunction(this, 'QueryForProductsThatNeedEnrichmentLambda', {
			entry: `${__dirname}/handlers/setup/index.ts`,
			env,
			name: `${serviceName}-setup-lambda`,
			environment: {
				ACCOUNT_ID: cdk.Stack.of(this).account,
			},
			memorySize: 512,
			timeout: cdk.Duration.seconds(20),
		})

		setupLambda.addToRolePolicy(
			new cdk.aws_iam.PolicyStatement({
				resources: ['*'],
				actions: ['states:ListExecutions'],
				effect: cdk.aws_iam.Effect.ALLOW,
			}),
		)

		const invokeSetupLambda = new cdk.aws_stepfunctions_tasks.LambdaInvoke(this, '1 Invoke Setup Lambda', {
			lambdaFunction: setupLambda,
			payload: cdk.aws_stepfunctions.TaskInput.fromObject({
				'executionId.$': '$$.Execution.Name',
				'stateMachineId.$': '$$.StateMachine.Name',
				'dataSource.$': '$.source',
				'batchSize.$': '$.batchSize',
				'forcedSkus.$': '$.forcedSkus',
			}),
			resultSelector: {
				'queryString.$': '$.Payload.queryString',
				'athenaOutputPrefix.$': '$.Payload.athenaOutputPrefix',
				'chunkedOutputPrefix.$': '$.Payload.chunkedOutputPrefix',
				'skipRun.$': '$.Payload.skipRun',
			},
			resultPath: '$.config',
		})

		const shouldSkipRun = new cdk.aws_stepfunctions.Choice(this, '1.1 Should Skip Run').when(
			cdk.aws_stepfunctions.Condition.booleanEquals('$.config.skipRun', true),
			new cdk.aws_stepfunctions.Succeed(this, 'Skip Run'),
		)

		const runAthenaQuery = new cdk.aws_stepfunctions.CustomState(this, '2. Run athena query', {
			stateJson: {
				Type: 'Task',
				Resource: 'arn:aws:states:::athena:startQueryExecution.sync',
				Parameters: {
					'QueryString.$': '$.config.queryString',
					WorkGroup: 'primary',
					ResultConfiguration: {
						'OutputLocation.$': `States.Format('s3://${productEnrichmentBucket.bucketName}/{}', $.config.athenaOutputPrefix)`,
						EncryptionConfiguration: {
							EncryptionOption: 'SSE_S3',
						},
					},
				},

				ResultPath: '$.athenaQuery',
				ResultSelector: {
					'outputPath.$': '$.QueryExecution.ResultConfiguration.OutputLocation',
				},
			},
		})

		const splitCsvLambda = new LambdaFunction(this, 'SplitCsvLambda', {
			entry: `${__dirname}/handlers/chunkCsv/index.ts`,
			env,
			environment: {
				ACCOUNT_ID: cdk.Stack.of(this).account,
				S3_BUCKET: productEnrichmentBucket.bucketName,
			},
			memorySize: 512,
			timeout: cdk.Duration.seconds(20),
		})

		const invokeSplitCsvLambda = new cdk.aws_stepfunctions_tasks.LambdaInvoke(this, '3 Invoke Split CSV Lambda', {
			lambdaFunction: splitCsvLambda,
			payload: cdk.aws_stepfunctions.TaskInput.fromObject({
				s3Bucket: productEnrichmentBucket.bucketName,
				'sourceS3Path.$': '$.config.athenaOutputPrefix',
				'batchSize.$': '$.chunkSizeRows',
			}),
			resultPath: '$.chunkPaths',
		})

		const attGen = new cdk.aws_stepfunctions.CustomState(this, 'Invoke Attribute Generator Lambda', {
			stateJson: {
				Type: 'Task',
				Resource: `arn:aws:states:eu-west-2:${cdk.Stack.of(this).account}:stateMachine:product-enrichment-attribute-generator`,
				Parameters: {
					'chunk.$': '$.chunk',
				},
				ResultPath: '$.attributeGeneratorResult',
			},
		})

		invokeSetupLambda.next(
			shouldSkipRun.otherwise(
				runAthenaQuery.next(invokeSplitCsvLambda).next(
					new cdk.aws_stepfunctions.Map(this, '4 For Each Chunk', {
						itemsPath: '$.chunkPaths',
						parameters: {
							'chunk.$': '$$.Map.Item.Value',
						},
					}).iterator(attGen),
				),
			),
		)

		const stateMachine = new cdk.aws_stepfunctions.StateMachine(this, 'AttributeGeneratorIrelandStateMachine', {
			definitionBody: cdk.aws_stepfunctions.DefinitionBody.fromChainable(invokeSetupLambda),
			stateMachineName: `${serviceName}-attribute-generator-ireland`,
		})

		stateMachine.addToRolePolicy(
			new cdk.aws_iam.PolicyStatement({
				resources: ['*'],
				actions: ['glue:*', 's3:Get*', 's3:List*', 'athena:*', 'lambda:*'],
				effect: cdk.aws_iam.Effect.ALLOW,
			}),
		)

		stateMachine.addToRolePolicy(
			new cdk.aws_iam.PolicyStatement({
				actions: ['bedrock:InvokeModel', 'bedrock:CreateModelInvocationJob', 'bedrock:GetModelInvocationJob', 'iam:PassRole'],
				effect: cdk.aws_iam.Effect.ALLOW,
