import * as cdk from 'aws-cdk-lib'
import { Construct } from 'constructs'
import { basename } from 'path'
import { StackProps } from '../../../cdk-services'
import { CategoryGenerator } from './constructs/category-generator/cdk'
import { S3Bucket } from '../../common/constructs/s3-bucket/s3Bucket'
import { AttributeGenerator } from './constructs/attribute-generator/cdk'
import { AmazonTranslator } from './constructs/amazon-translator/cdk'
import { FeaturesGenerator } from './constructs/feature-generator/cdk'
import { InternationalBedrockTrigger } from './constructs/international-bedrock-trigger/cdk'
import { AttributesGeneratorIreland } from './constructs/attributes-generator-ireland/cdk'

const serviceName = basename(__dirname) // derive from directory

export class ProductEnrichmentService extends cdk.Stack {
	constructor(scope: Construct, id: string, props: StackProps) {
		super(scope, id, props)

		const env = props.environment.ENV

		const productEnrichmentBucket = new S3Bucket(this, 'ProductEnrichmentBucket', {
			name: 'data',
			env,
			serviceName,
			eventBridge: false,
			autoDeleteObjects: true,
		})

		const internationalBedrockTrigger = new InternationalBedrockTrigger(this, 'InternationalBedrockTrigger', {
			env,
			serviceName,
		})

		new CategoryGenerator(this, 'CategoryGenerator', {
			env,
			serviceName,
			productEnrichmentBucket,
		})

		const attGen = new AttributeGenerator(this, 'AttributeGenerator', {
			env,
			serviceName,
			productEnrichmentBucket,
			internationalBedrockTriggerLambda: internationalBedrockTrigger.internationalLambda,
		})

		const attGenIe = new AttributesGeneratorIreland(this, 'AttributesGenerator', {
			env,
			serviceName,
			productEnrichmentBucket,
		})

		attGenIe.node.addDependency(attGen) // ensure Ireland runs after UK

		new FeaturesGenerator(this, 'FeaturesGenerator', {
			env,
			serviceName,
			productEnrichmentBucket,
		})

		new AmazonTranslator(this, 'AmazonTranslator', {
			env,
			serviceName,
			productEnrichmentBucket,
		})
	}
}

